// 每位讀者執行一次（Mode: Run Once for Each Item）
const cfg = $('設定').first().json;
const r = $json;
const days = Number(r.max_overdue_days);
const fine = Number(r.total_overdue_days) * cfg.fine_per_day;

let level, color, intro;
if (days >= 30) {
  level = '最後通知'; color = '#dc2626';
  intro = '您借閱的書籍已逾期超過 30 天，若 7 天內仍未歸還，將暫停您的借閱權利。';
} else if (days >= 7) {
  level = '再次提醒'; color = '#ea580c';
  intro = '您借閱的書籍已逾期一段時間，其他讀者正在等候，請盡快歸還。';
} else {
  level = '溫馨提醒'; color = '#2563eb';
  intro = '您借閱的書籍已經到期囉，記得找時間拿來歸還喔！';
}

const rows = r.books.map(b => `
  <tr>
    <td style="padding:6px 8px">${b.title}</td>
    <td style="padding:6px 8px">${b.due_date}</td>
    <td style="padding:6px 8px;color:${color};text-align:right">${b.overdue_days} 天</td>
  </tr>`).join('');

const html = `
<div style="font-family:Arial,sans-serif;max-width:560px;margin:auto">
  <h2 style="color:${color}">📚 ${cfg.library_name}｜還書${level}</h2>
  <p>${r.name} 您好：</p>
  <p>${intro}</p>
  <table style="width:100%;border-collapse:collapse;font-size:14px">
    <tr style="background:#f3f4f6"><th style="padding:6px 8px;text-align:left">書名</th><th style="padding:6px 8px;text-align:left">到期日</th><th style="padding:6px 8px;text-align:right">逾期</th></tr>
    ${rows}
  </table>
  <p>目前累計逾期罰款：<b>${fine} 元</b>（每本每天 ${cfg.fine_per_day} 元）</p>
  <p style="color:#6b7280;font-size:13px">若您已歸還，請忽略此信。</p>
</div>`;

return {
  json: {
    member_id: r.member_id,
    to: cfg.test_email || r.email,   // 有填 test_email 就寄給自己測試
    subject: `【${level}】${r.name} 您好，您有 ${r.books.length} 本書已逾期`,
    html,
  },
};
